declare(strict_types=1); namespace Comfino\Common\Backend\Payment\ProductTypeFilter; use Comfino\Api\Dto\Payment\LoanTypeEnum; use Comfino\Common\Backend\Payment\ProductTypeFilterInterface; use Comfino\Common\Shop\Cart; class FilterByProductType implements ProductTypeFilterInterface{ private $allowedProductTypes; public function __construct(array$allowedProductTypes){$this->allowedProductTypes=$allowedProductTypes;} public function getAllowedProductTypes($availableProductTypes,$cart):array{return array_intersect($this->allowedProductTypes,$availableProductTypes);}public function getAsArray():array{return['allowedProductTypes'=>$this->allowedProductTypes];}}